test('generateRememberToken returns a url-safe, high-entropy token', () => {
  const token = generateRememberToken('u1');
  // 32 random bytes base64url-encoded is 43 chars; guards against a weak generator.
  assert.ok(token.length >= 43, `expected >=43 chars, got ${token.length}`);
  assert.match(token, /^[A-Za-z0-9_-]+$/);
});

test('validateRememberToken accepts a token issued for that user', () => {
  const token = generateRememberToken('u1');
  assert.strictEqual(validateRememberToken(token), 'u1');
});

test('validateRememberToken rejects an unknown token', () => {
  assert.strictEqual(validateRememberToken('not-a-real-token'), null);
});

test('validateRememberToken rejects a tampered token', () => {
  const token = generateRememberToken('u1');
  const tampered = token.slice(0, -1) + (token.at(-1) === 'a' ? 'b' : 'a');
  assert.strictEqual(validateRememberToken(tampered), null);
});

test('validateRememberToken rejects missing/malformed input without throwing', () => {
  assert.strictEqual(validateRememberToken(undefined), null);
  assert.strictEqual(validateRememberToken(null), null);
  assert.strictEqual(validateRememberToken(''), null);
  assert.strictEqual(validateRememberToken(42), null);
});

test('remember tokens are distinct per call', () => {
  const a = generateRememberToken('u1');
  const b = generateRememberToken('u1');
  assert.notStrictEqual(a, b);
});

test('remember token is rejected once revoked', () => {
  const token = generateRememberToken('u1');
  revokeRememberToken(token);
  assert.strictEqual(validateRememberToken(token), null);
});

test('remember token expires after its TTL', (t) => {
  t.mock.timers.enable({ apis: ['Date'] });
  const token = generateRememberToken('u1');
  assert.strictEqual(validateRememberToken(token), 'u1');
  t.mock.timers.tick(31 * 24 * 60 * 60 * 1000); // 31 days
  assert.strictEqual(validateRememberToken(token), null);
});

